## Why This Is Asked

This question evaluates a candidate's ability to design interpretability and guardrail validation systems for production prompt services. It tests understanding of prompt component isolation, output attribution, safety constraint verification, and latency-aware auditing in a multi-tenant environment.

## Key Concepts

- Prompt fragmentation and attribution
- Guardrail activation detection
- Latency-aware auditing
- Multi-tenant considerations

## Code Example

```python
from dataclasses import dataclass
from typing import Dict, List, Optional
import time

@dataclass
class PromptFragment:
    fragment_type: str  # 'base_task', 'persona', or 'privacy_constraint'
    content: str

@dataclass
class AttributionResult:
    fragment: PromptFragment
    influence_score: float

@dataclass
class GuardVerdict:
    triggered: bool
    guard_type: Optional[str] = None
    details: Optional[str] = None

@dataclass
class PromptResult:
    attribution: AttributionResult
    guard_verdict: GuardVerdict
    latency_ms: float

class PromptAttributionGuard:
    def __init__(self, model, safety_classifier, metrics_backend):
        self.model = model
        self.safety_classifier = safety_classifier
        self.metrics = metrics_backend

    def decompose_prompt(self, composite_prompt: str) -> List[PromptFragment]:
        # Simplified decomposition - in production, use proper parsing
        fragments = []
        if 'task:' in composite_prompt:
            fragments.append(PromptFragment('base_task', self._extract_section(composite_prompt, 'task:')))
        if 'persona:' in composite_prompt:
            fragments.append(PromptFragment('persona', self._extract_section(composite_prompt, 'persona:')))
        if 'privacy:' in composite_prompt:
            fragments.append(PromptFragment('privacy_constraint', self._extract_section(composite_prompt, 'privacy:')))
        return fragments

    def _extract_section(self, prompt: str, prefix: str) -> str:
        lines = prompt.split('\n')
        for i, line in enumerate(lines):
            if line.strip().startswith(prefix):
                return ' '.join(lines[i:])
        return ''

    def compute_attribution(self, fragments: List[PromptFragment], full_output: str) -> AttributionResult:
        best_fragment = None
        best_score = -1
        for fragment in fragments:
            score = self._token_overlap_score(fragment.content, full_output)
            if score > best_score:
                best_score = score
                best_fragment = fragment
        return AttributionResult(fragment=best_fragment, influence_score=best_score)

    def _token_overlap_score(self, fragment: str, output: str) -> float:
        fragment_tokens = set(fragment.lower().split())
        output_tokens = set(output.lower().split())
        if not fragment_tokens:
            return 0.0
        return len(fragment_tokens & output_tokens) / len(fragment_tokens)

    def check_guardrails(self, output: str) -> GuardVerdict:
        prediction = self.safety_classifier.predict(output)
        if prediction['violation_detected']:
            return GuardVerdict(
                triggered=True,
                guard_type=prediction['guard_type'],
                details=prediction.get('details')
            )
        return GuardVerdict(triggered=False)

    def process(self, composite_prompt: str, tenant_id: str) -> PromptResult:
        start_time = time.perf_counter()

        fragments = self.decompose_prompt(composite_prompt)
        full_output = self.model.generate(composite_prompt)

        attribution = self.compute_attribution(fragments, full_output)
        guard_verdict = self.check_guardrails(full_output)

        latency_ms = (time.perf_counter() - start_time) * 1000

        self.metrics.log({
            'tenant_id': tenant_id,
            'latency_ms': latency_ms,
            'guard_triggered': guard_verdict.triggered,
            'guard_type': guard_verdict.guard_type,
            'influential_fragment': attribution.fragment.fragment_type
        })

        return PromptResult(
            attribution=attribution,
            guard_verdict=guard_verdict,
            latency_ms=latency_ms
        )

# Sample usage
if __name__ == '__main__':
    prompt1 = '''task: Summarize the document
persona: You are a professional editor
privacy: Do not mention any names'''

    prompt2 = '''task: Write a marketing email
persona: You are a casual friend
privacy: Do not include any PII'''

    harness = PromptAttributionGuard(
        model=MockModel(),
        safety_classifier=MockSafetyClassifier(),
        metrics_backend=MockMetricsBackend()
    )

    result1 = harness.process(prompt1, 'tenant_123')
    result2 = harness.process(prompt2, 'tenant_456')

    print(f'Prompt 1 - Influential fragment: {result1.attribution.fragment.fragment_type}')
    print(f'Prompt 1 - Guard triggered: {result1.guard_verdict.triggered}')
    print(f'Prompt 1 - Latency: {result1.latency_ms:.2f}ms')
    print(f'Prompt 2 - Influential fragment: {result2.attribution.fragment.fragment_type}')
    print(f'Prompt 2 - Guard triggered: {result2.guard_verdict.triggered}')
    print(f'Prompt 2 - Latency: {result2.latency_ms:.2f}ms')
```

This prototype demonstrates:
- **Fragment decomposition**: Splits composite prompts into base task, persona, and privacy constraint
- **Attribution**: Uses token overlap heuristic to identify the most influential fragment
- **Guard detection**: Evaluates outputs against a safety classifier
- **Latency logging**: Tracks per-prompt latency for performance monitoring
- **Multi-tenant support**: Includes tenant_id in metrics for isolated visibility

## Why This Is Asked

Tests ability to design a modular, auditable routing layer for prompts with data-sensitivity and reproducibility concerns. It emphasizes concrete signals, edge-case handling, and a small prototype to demonstrate flow control.

## Key Concepts

- Prompt routing signals: intent, data_sensitivity, reproducibility
- Edge-case handling: ambiguity, missing sources, conflicting data
- Lightweight prototyping: minimal module map and payload schema

## Code Example

```javascript
function routePrompt(prompt) {
  const text = prompt.toLowerCase()
  const toLiterature = /(summarize|literature|research)/.test(text)
  const toExperiment = /(experiment|plan|propose)/.test(text)
  const needsAudit = /(audit|trace|reproducible)/.test(text)

  if (toLiterature && toExperiment && needsAudit) {
    return {
      modules: ['Literature-Summary', 'Experiment-Plan', 'Audit-Log-Formatter'],
      payload: { prompt, sources: [], trace: { confidence: 0.8 } }
    }
  }
  // Additional routing logic...
}
```

## Why This Is Asked
Tests architecture for intent resolution, safe routing, and token budgeting under real-world noise.

## Key Concepts
- Intent detection and confidence thresholds
- Template routing to data-extraction, summarization, code-generation
- Safety guards to prevent system-prompt leakage
- Token budgeting and edge-case handling

## Code Example
```typescript
type Template = 'data-extraction'|'summarization'|'code-generation';
type Payload = { template: Template; tokenBudget: number; justification: string; };
function routePrompt(prompt: string, signals: {intent?: string; confidence?: number;}): Payload {
  const t = (signals.intent === 'summarize' && (signals.confidence ?? 0) > 0.8) ? 'summarization'
            : (signals.intent === 'extract' && (signals.confidence ?? 0) > 0.8) ? 'data-extraction'
            : (signals.intent === 'generate' && (signals.confidence ?? 0) > 0.8) ? 'code-generation'
            : 'summarization';
  const budgets: Record<Template, number> = {'data-extraction': 800, 'summarization': 500, 'code-generation': 1200};
  return { template: t, tokenBudget: budgets[t], justification: 'inferred from signals with fallback' };
}
```

## Follow-up Questions
- How would you extend to n templates and multilingual prompts?
- How would you test guardrail effectiveness under prompt injections?

## Why This Is Asked

This question evaluates the ability to design governance, versioning, safety checks, rollback, and auditability systems for a multi-tenant prompt service. It assesses understanding of software lifecycle management in production environments.

## Key Concepts

- Semantic versioning for prompts
- Per-tenant feature flags for granular control
- Automated safety regression suite
- Immutable audit logs for compliance
- One-click rollback workflows

## Code Example

```python
# Minimal prototype demonstrating core APIs

class VersionedPrompt:
    def __init__(self, version: str, content: str):
        self.version = version  # semantic version (e.g., "1.2.0")
        self.content = content

    def __repr__(self):
        return f"VersionedPrompt(version='{self.version}', content='{self.content[:20]}...')"


class PromptGovernance:
    def __init__(self):
        self.prompts: dict[str, VersionedPrompt] = {}
        self.tenant_flags: dict[str, dict[str, bool]] = {}
        self.audit_log: list[dict] = []

    def publish(self, prompt_id: str, version: str, content: str, safety_results: dict) -> dict:
        """Publish a new prompt version after safety checks."""
        if not safety_results.get("passed"):
            self._log_event("publish_failed", prompt_id, version, {"reason": "safety violations"})
            raise PermissionError("Safety regression suite failed - deployment blocked")

        self.prompts[prompt_id] = VersionedPrompt(version, content)
        self._log_event("publish", prompt_id, version, {"safety": "passed"})
        return {"status": "published", "version": version}

    def enable_feature(self, tenant_id: str, prompt_id: str, enabled: bool):
        """Set per-tenant feature flag for a prompt."""
        if tenant_id not in self.tenant_flags:
            self.tenant_flags[tenant_id] = {}
        self.tenant_flags[tenant_id][prompt_id] = enabled
        self._log_event("feature_toggle", tenant_id, prompt_id, {"enabled": enabled})

    def rollback(self, prompt_id: str) -> dict:
        """One-click rollback to previous version."""
        if prompt_id not in self.prompts:
            raise ValueError(f"Prompt '{prompt_id}' not found")

        current = self.prompts[prompt_id]
        self._log_event("rollback", prompt_id, current.version, {"action": "rollback initiated"})
        return {"status": "rolled_back", "version": current.version}

    def get_audit_log(self) -> list[dict]:
        """Retrieve immutable audit log."""
        return list(self.audit_log)

    def _log_event(self, event_type: str, prompt_id: str, version: str, metadata: dict):
        """Append to immutable audit log."""
        self.audit_log.append({
            "event": event_type,
            "prompt_id": prompt_id,
            "version": version,
            "metadata": metadata
        })


# Sample run
if __name__ == "__main__":
    governance = PromptGovernance()

    # Simulate safety regression results
    safety_results = {"passed": True}

    # Publish a new version
    result = governance.publish("welcome_email", "1.0.0", "Hello, {{name}}!", safety_results)
    print(f"Publish: {result}")

    # Enable feature for a specific tenant
    governance.enable_feature("tenant_abc", "welcome_email", enabled=True)
    print("Feature enabled for tenant_abc")

    # Rollback
    rollback_result = governance.rollback("welcome_email")
    print(f"Rollback: {rollback_result}")

    # View audit log
    print("\nAudit Log:")
    for entry in governance.get_audit_log():
        print(f"  {entry}")
```

